  const tells = ['vocab','filler','opener','negclose','emdash'].reduce((a, k) => a + (rep[k] || 0), 0)
  const toks = p.toLowerCase().replace(/[*_#>]/g, ' ').match(/[a-z0-9']+/g) || []
  const seen = new Map<string, number>()
  for (let i = 0; i + 6 <= toks.length; i++) { const g = toks.slice(i, i + 6).join(' '); seen.set(g, (seen.get(g) || 0) + 1) }
  return {
    words: lens.reduce((a, b) => a + b, 0),
    avgSent: lens.length ? lens.reduce((a, b) => a + b, 0) / lens.length : 0,
    pctLong: lens.length ? 100 * lens.filter(n => n > 25).length / lens.length : 0,
    tells,
    bold: (p.match(/\*\*[^*\n]+\*\*/g) || []).length,
    repeats: [...seen.values()].filter(c => c > 1).length,
  }
}
const rows: R[] = []; const invalid: Record<string, number> = {}
for (const f of readdirSync(OUT).filter(f => f.endsWith('.txt'))) {
  const [v, key, rep] = f.replace('.txt', '').split(/_(?=[^_]+_\d+$)|_(?=\d+$)/)
  const text = readFileSync(`${OUT}/${f}`, 'utf8')
