const vm = (v: string, m: typeof M[number]) => mean(of(v).map(r => r[m]))
// noise for full: (T1) SD of the 3 rep-means; (T2) pooled within-cell SD across reps for the same prompt
const T1: any = {}, T2: any = {}
for (const m of M) {
