  const keys = [...new Set(of('full').map(r => r.key))]
  const vars = keys.map(k => { const a = of('full').filter(r => r.key === k).map(r => r[m]); return a.length > 1 ? sd(a) ** 2 : NaN }).filter(x => !isNaN(x))
  T2[m] = Math.sqrt(mean(vars))
}
const f2 = (x: number) => x.toFixed(2)
let o = `| variant | valid | ${M.join(' | ')} |\n|---|---|${M.map(() => '---').join('|')}|\n`
for (const v of VARS) o += `| ${v} | ${of(v).length}/30 | ${M.map(m => f2(vm(v, m))).join(' | ')} |\n`
