o += `\n**Difference from none**\n\n| variant | ${M.join(' | ')} |\n|---|${M.map(() => '---').join('|')}|\n`
for (const v of VARS.filter(v => v !== 'none')) o += `| ${v} | ${M.map(m => { const d = vm(v, m) - vm('none', m); return (d >= 0 ? '+' : '') + f2(d) }).join(' | ')} |\n`
o += `\nNoise for full. T1 = SD of 3 rep-means: ${M.map(m => m + '=' + f2(T1[m])).join(', ')}\n`
o += `Per-run spread T2 = pooled within-prompt SD: ${M.map(m => m + '=' + f2(T2[m])).join(', ')}\n`
o += `Invalid runs excluded (after retry): ${JSON.stringify(invalid)}\n`
